#!/usr/bin/env bash
# СУДИТ: hooks/completion-gate.sh
# probe_D441.sh — проба пункта D441: completion-gate.sh молчит на ЗАКРЫТОМ (☑) пункте без
# разобранной команды «Проверки» либо без строки «Результат.» — тот же корень (R6), что у D431,
# но в БРАТЕ, которого D431 не трогал (commit 444677f: «hooks/completion-gate.sh не тронуты»).
# Результат: ☑-пункт без команды в обратных кавычках (B1) и ☑-пункт без «Результат.» (B2) на Stop
#            называются гейтом; ☑-пункт по контракту (и команда, и «Результат.») остаётся немым.
# Проверка результата: bash hooks/tests/fixtures/probe_D441.sh даёт 0
#
# Коды: 0 — желаемое поведение соблюдено; 1 — дефект наблюдён (стдерр называет, какой пункт
# остался немым); 2 — рамка не собралась (стдерр называет, чего не хватает).
# Механизм под судом берётся из CLAUDSOUL_REPO (зелёная сторона подставляет копию с починкой),
# собственный корень — от пути этого файла. Живой ~/.claude не читается: HOME подменён.
# Судится РЕАЛЬНАЯ точка доставки Stop-хука — очередь $STATE/pending-alerts.txt, а не собственный
# stdout completion-gate.sh: сырые строки `#CG_*` там режутся общим `grep -v '^#CG_'` (:571), и
# то, что не дошло именованным каналом до `_join`, в очередь не попадает вовсе (rc всегда 0).
# D906 — положительный контроль РАМКИ (не защита D901/D902): открытый пункт без строки
# «Проверка» обязан дать канал #CG_OPEN независимо от патча. Без него единственный контроль —
# «D903 не назван» — отрицательный и проходит даром, когда механизм вовсе не запустился
# (например state-lock-lib.sh не попал в зелёную копию, и with_lock в completion-gate.sh:166
# не определён): очередь пуста не от отсутствия дефекта, а оттого, что python-разбор внутри
# completion-gate.sh не исполнился вовсе. Порядок проверок ниже поэтому такой: сперва рамка
# (D906), потом негативный контроль (D903), потом сам дефект (D901/D902).
set -uo pipefail
. "$(dirname "$0")/../alerts-read.sh"
ROOT="$(cd "$(dirname "$0")/../../.." && pwd -P)"
MECH="${CLAUDSOUL_REPO:-$ROOT}"
GATE="$MECH/hooks/completion-gate.sh"
[ -f "$GATE" ] || { echo "probe_D441: нет $GATE" >&2; exit 2; }
[ -f "$MECH/hooks/backlog-lib.sh" ] || { echo "probe_D441: нет $MECH/hooks/backlog-lib.sh" >&2; exit 2; }
command -v jq >/dev/null 2>&1 || { echo "probe_D441: нужен jq" >&2; exit 2; }
command -v python3 >/dev/null 2>&1 || { echo "probe_D441: нужен python3" >&2; exit 2; }
T=$(mktemp -d) || { echo "probe_D441: нет временного каталога" >&2; exit 2; }
trap 'rm -rf "$T"' EXIT
mkdir -p "$T/home" "$T/state"
cat > "$T/BACKLOG.md" <<'EOF'
# BACKLOG

## Раздел

- ☑ **D901** Закрыт, а в строке «Проверка.» нет команды (B1).
  **Результат.** Есть.
  **Проверка.** пока не определена.

- ☑ **D902** Закрыт зелёной командой, а строки «Результат.» нет (B2).
  **Проверка.** `true` → 0

- ☑ **D903** Закрыт по контракту: и результат, и команда (положительный контроль).
  **Результат.** Есть.
  **Проверка.** `true` → 0

- ☐ **D906** Открытый пункт без строки «Проверка» (положительный контроль рамки).
EOF
unset BACKLOG_CHECKS_NESTED    # рамку задаёт проба, а не окружение (D334)
INPUT=$(jq -cn --arg cwd "$T" '{cwd:$cwd, session_id:"probe-d441"}')
STDOUT=$(printf '%s' "$INPUT" | HOME="$T/home" STATE_DIR="$T/state" CG_BACKLOG="$T/BACKLOG.md" \
      CLAUDSOUL_ROOT="$MECH" bash "$GATE" 2>&1)
RC=$?
QOUT=$(alerts_of "$T/state")

# Положительный контроль РАМКИ: D906 — открытый пункт без строки «Проверка» — обязан дать
# #CG_OPEN независимо от патча (канал существовал уже у D264, до этой пробы). Не назван —
# значит python-разбор внутри completion-gate.sh не исполнился вовсе (например, недостаёт
# библиотеки в раскладке MECH), и молчание на D901/D902 ничего не доказывает про дефект.
if ! grep -q 'D906' <<< "$QOUT"; then
    echo "probe_D441: рамка не собралась — открытый пункт D906 без строки «Проверка» не назван (rc=$RC); механизм, похоже, не исполнился (недостающая библиотека?); stdout: [$STDOUT]; очередь: [$QOUT]" >&2
    exit 2
fi

# Положительный контроль ДЕФЕКТА: закрытие по контракту (D903) молчать ОБЯЗАНО — иначе гейт
# кричит на всё подряд, и «называет D901/D902» ничего не доказывает.
if grep -q 'D903' <<< "$QOUT"; then
    echo "probe_D441: положительный контроль не прошёл — очередь назвала закрытие по контракту D903: [$QOUT]" >&2
    exit 2
fi

MISSING=""
grep -q 'D901' <<< "$QOUT" || MISSING="$MISSING D901(нет команды)"
grep -q 'D902' <<< "$QOUT" || MISSING="$MISSING D902(нет «Результат.»)"

if [ -n "$MISSING" ]; then
    echo "probe_D441: дефект — каналы сообщений (общая очередь, сессия, проект) молчат на слепом закрытии (rc=$RC):$MISSING; stdout: [$STDOUT]; очередь: [$QOUT]" >&2
    exit 1
fi
exit 0
